// ── Live Catalog Sync Runtime (Local Override + Cloudflare KV Cloud Sync) ──
window.__AQUA_SYNC_RUNTIME_FN__ = function () {
  if (typeof window === "undefined" || !window.AQUA_PARTS_CATALOG) return;

  const STORAGE_KEY = "aqua-parts-catalog-override-v1";
  const BUILD_EPOCH_MS = 1794930622316;
  window.AQUA_CATALOG_STORAGE_KEY = STORAGE_KEY;

  function isFreshOverride(ts, catData) {
    const candidate = ts || (catData && (catData.updatedAt || catData.generatedAt)) || "";
    const parsedMs = candidate ? Date.parse(candidate) : NaN;
    return Number.isFinite(parsedMs) && parsedMs >= BUILD_EPOCH_MS;
  }

  // Keep a pristine deep clone of the factory baseline catalog
  if (!window.AQUA_PARTS_DEFAULT_CATALOG) {
    try {
      window.AQUA_PARTS_DEFAULT_CATALOG = JSON.parse(
        JSON.stringify(window.AQUA_PARTS_CATALOG)
      );
    } catch (_) {}
  }

  const SKU_PREFIX_MAP = {
    monitors: "MON",
    "vga-cards": "VGA",
    processors: "CPU",
    motherboards: "MBD",
    storage: "STR",
    ram: "RAM",
    "power-supply": "PSU",
    cooling: "CLG",
    cables: "CBL",
    peripherals: "PER",
    laptops: "LTP",
    desktops: "DSK",
    casings: "CAS",
    "bn-laptops": "BNL",
    "bn-desktops": "BND",
    "bn-monitors": "BMN",
    "bn-vga-cards": "BNV",
    "bn-processors": "BNC",
    "bn-motherboards": "BNM",
    "bn-ram": "BNR",
    "bn-storage": "BNS",
    "bn-power-supply": "BNP",
    "bn-cooling": "BNG",
    "bn-casings": "BNA",
    "bn-keyboards": "BNK",
    "bn-mice": "BNI",
    "bn-audio": "BNO",
    "bn-webcams": "BNW",
    "bn-microphones": "BNR",
    "bn-sound-cards": "BNS",
    "bn-cables": "BNB",
    "bn-gaming-chairs": "BCH",
    "bn-accessories": "BNX",
    "bn-components": "BNP",
  };

  function getSkuPrefix(secId, isNew) {
    if (SKU_PREFIX_MAP[secId]) return SKU_PREFIX_MAP[secId];
    const clean =
      String(secId || "PRT")
        .replace(/^bn-/, "")
        .replace(/[^a-z0-9]/gi, "")
        .toUpperCase()
        .slice(0, 3) || "PRT";
    return (isNew ? "BN" + clean.slice(0, 1) : clean).padEnd(3, "X");
  }

  window.generateAquaSku = function (secId, isNew, seqNum) {
    const prefix = getSkuPrefix(secId, isNew);
    const num = Number.isFinite(Number(seqNum)) && Number(seqNum) > 0
      ? Math.floor(Number(seqNum))
      : Math.floor(1000 + Math.random() * 9000);
    return "AQ-" + prefix + "-" + String(num).padStart(4, "0");
  };

  function ensureCatalogSkus(target) {
    if (!target || typeof target !== "object") return;
    const defaultById = {};
    const collectDefaults = (secs, isNew) => {
      (secs || []).forEach((s) => {
        (s.categories || []).forEach((c) => {
          (c.items || []).forEach((it) => {
            if (it && it.id && it.sku) {
              defaultById[(isNew ? "new:" : "used:") + it.id] = it.sku;
            }
          });
        });
      });
    };
    if (window.AQUA_PARTS_DEFAULT_CATALOG) {
      collectDefaults(window.AQUA_PARTS_DEFAULT_CATALOG.usedSections || window.AQUA_PARTS_DEFAULT_CATALOG.sections, false);
      collectDefaults(window.AQUA_PARTS_DEFAULT_CATALOG.brandNewSections, true);
    }

    const usedSkus = new Set();
    const counters = {};
    const pass = (secs, isNew) => {
      (secs || []).forEach((s) => {
        const prefix = getSkuPrefix(s && s.id, isNew);
        if (!counters[prefix]) counters[prefix] = 0;
        (s.categories || []).forEach((c) => {
          (c.items || []).forEach((it) => {
            if (!it || typeof it !== "object") return;
            if (it.sku) {
              usedSkus.add(it.sku);
              return;
            }
            const key = (isNew ? "new:" : "used:") + it.id;
            if (defaultById[key]) {
              it.sku = defaultById[key];
              usedSkus.add(it.sku);
              return;
            }
            let candidate = "";
            do {
              counters[prefix]++;
              candidate = "AQ-" + prefix + "-" + String(counters[prefix]).padStart(4, "0");
            } while (usedSkus.has(candidate));
            it.sku = candidate;
            usedSkus.add(candidate);
          });
        });
      });
    };
    pass(target.usedSections || target.sections, false);
    pass(target.sections, false);
    pass(target.brandNewSections, true);
  }

  ensureCatalogSkus(window.AQUA_PARTS_CATALOG);

  function countSecs(secs) {
    if (!Array.isArray(secs)) return 0;
    return secs.reduce(
      (sum, s) =>
        sum +
        (Array.isArray(s.categories)
          ? s.categories.reduce(
              (cs, c) => cs + (Array.isArray(c.items) ? c.items.length : 0),
              0
            )
          : 0),
      0
    );
  }

  window.applyAquaCatalogOverride = function (incoming, skipEvent) {
    if (!incoming || typeof incoming !== "object") return;
    const target = window.AQUA_PARTS_CATALOG;

    const nextUsed = Array.isArray(incoming.usedSections)
      ? incoming.usedSections
      : Array.isArray(incoming.sections)
      ? incoming.sections
      : null;

    const nextNew = Array.isArray(incoming.brandNewSections)
      ? incoming.brandNewSections
      : null;

    if (nextUsed) {
      if (Array.isArray(target.usedSections)) {
        target.usedSections.splice(0, target.usedSections.length, ...nextUsed);
      } else {
        target.usedSections = nextUsed.slice();
      }
      if (Array.isArray(target.sections)) {
        target.sections.splice(0, target.sections.length, ...nextUsed);
      } else {
        target.sections = nextUsed.slice();
      }
    }

    if (nextNew) {
      if (Array.isArray(target.brandNewSections)) {
        target.brandNewSections.splice(0, target.brandNewSections.length, ...nextNew);
      } else {
        target.brandNewSections = nextNew.slice();
      }
    }

    ensureCatalogSkus(target);

    // Recompute counts accurately
    const usedTotal = countSecs(target.usedSections);
    const newTotal = countSecs(target.brandNewSections);
    target.usedTotalItems = usedTotal;
    target.totalItems = usedTotal;
    target.brandNewTotalItems = newTotal;

    const secCounts = {};
    (target.usedSections || []).forEach((s) => {
      secCounts[s.id] = countSecs([s]);
    });
    target.sectionItemCounts = secCounts;

    const bnCounts = {};
    (target.brandNewSections || []).forEach((s) => {
      bnCounts[s.id] = countSecs([s]);
    });
    target.brandNewSectionItemCounts = bnCounts;

    if (incoming.whatsappPhone) target.whatsappPhone = incoming.whatsappPhone;
    if (incoming.whatsappDirectBase) target.whatsappDirectBase = incoming.whatsappDirectBase;

    if (!skipEvent) {
      try {
        window.dispatchEvent(
          new CustomEvent("aqua:catalog-updated", { detail: target })
        );
      } catch (_) {}
    }
  };

  // 1. Apply local cache synchronously on boot only if newer than this catalog build
  try {
    const cachedRaw = localStorage.getItem(STORAGE_KEY);
    if (cachedRaw) {
      const parsed = JSON.parse(cachedRaw);
      const catData = parsed && parsed.catalog ? parsed.catalog : parsed;
      const cachedTs = parsed && parsed.updatedAt ? parsed.updatedAt : "";
      if (catData && (catData.usedSections || catData.brandNewSections) && isFreshOverride(cachedTs, catData)) {
        window.applyAquaCatalogOverride(catData, true);
      } else {
        localStorage.removeItem(STORAGE_KEY);
      }
    }
  } catch (_) {}

  // 2. Fetch latest live cloud catalog from Cloudflare D1 (/api/catalog with cross-origin fallback)
  if (typeof fetch === "function" && /^https?:/i.test(window.location.protocol)) {
    const cloudFallback = "https://aquapcsolutions.yyth.workers.dev/api/catalog";
    const fetchInit = {
      method: "GET",
      headers: { Accept: "application/json" },
      cache: "no-store",
    };
    fetch("/api/catalog", fetchInit)
      .then((r) => {
        if (r.ok) return r.json();
        if (window.location.origin !== "https://aquapcsolutions.yyth.workers.dev") {
          return fetch(cloudFallback, fetchInit).then((cr) => (cr.ok ? cr.json() : null));
        }
        return null;
      })
      .catch(() =>
        window.location.origin !== "https://aquapcsolutions.yyth.workers.dev"
          ? fetch(cloudFallback, fetchInit).then((cr) => (cr.ok ? cr.json() : null)).catch(() => null)
          : null
      )
      .then((res) => {
        if (res && res.ok && res.hasCloudData && res.catalog) {
          if (!isFreshOverride(res.updatedAt, res.catalog)) {
            return;
          }
          try {
            localStorage.setItem(
              STORAGE_KEY,
              JSON.stringify({
                updatedAt: res.updatedAt || new Date().toISOString(),
                catalog: res.catalog,
              })
            );
          } catch (_) {}
          window.applyAquaCatalogOverride(res.catalog, false);
        }
      })
      .catch(() => {});
  }
};
window.__AQUA_SYNC_RUNTIME_FN__();
